const p = $json;
const repo = p.repository || {};
const pr = p.pull_request;
const issue = p.issue;
const review = p.review;
const comment = p.comment;
const checkRun = p.check_run;
const checkSuite = p.check_suite;
const release = p.release;
const deployment = p.deployment;
const deploymentStatus = p.deployment_status;
const alert = p.alert;
const advisory = p.security_advisory;
const sender = p.sender?.login || '';
const action = String(p.action || p.state || checkRun?.status || checkSuite?.status || deploymentStatus?.state || 'updated');
let family = 'repository';
if (pr && review) family = 'pull_request_review';
else if (pr && comment) family = 'pull_request_review_comment';
else if (pr) family = 'pull_request';
else if (issue && comment) family = 'issue_comment';
else if (issue) family = 'issues';
else if (checkRun) family = 'check_run';
else if (checkSuite) family = 'check_suite';
else if (release) family = 'release';
else if (deploymentStatus) family = 'deployment_status';
else if (deployment) family = 'deployment';
else if (advisory) family = 'security_advisory';
else if (alert) family = 'repository_vulnerability_alert';
else if (p.head_commit || (p.before && p.after && p.ref)) family = 'push';
else if (p.sha && p.context && p.state) family = 'status';
else if (comment?.commit_id) family = 'commit_comment';
const markerText = String(comment?.body || review?.body || release?.body || '');
const selfGenerated = sender === 'NTLx' && markerText.includes('<!-- chatgpt:n8n -->');
const conclusion = String(checkRun?.conclusion || checkSuite?.conclusion || p.state || deploymentStatus?.state || '');
const failed = ['failure','failed','error','timed_out','action_required','cancelled','stale'].includes(conclusion);
let shouldEnqueue = !selfGenerated;
if (family === 'check_run' || family === 'check_suite' || family === 'status' || family === 'deployment_status') shouldEnqueue = shouldEnqueue && failed;
if (family === 'deployment') shouldEnqueue = false;
let kind = 'github_repository_review';
if (family.startsWith('pull_request')) kind = 'github_pr_review';
else if (family === 'issues') kind = 'github_issue_triage';
else if (family === 'issue_comment' || family === 'commit_comment') kind = 'github_discussion_review';
else if (family === 'check_run' || family === 'check_suite' || family === 'status') kind = 'ci_triage';
else if (family === 'release') kind = 'release_review';
else if (family.startsWith('deployment')) kind = 'github_deployment_review';
else if (family === 'repository_vulnerability_alert' || family === 'security_advisory') kind = 'github_security_review';
else if (family === 'push') kind = 'github_push_review';
let priority = 50;
if (kind === 'github_security_review') priority = 5;
else if (kind === 'ci_triage' || kind === 'github_deployment_review') priority = 10;
else if (kind === 'github_pr_review' || kind === 'release_review') priority = 25;
else if (kind === 'github_issue_triage' || kind === 'github_discussion_review') priority = 35;
let unique = 'unknown';
if (family === 'pull_request_review') unique = [review?.id || 'review', review?.submitted_at || review?.updated_at || ''].join(':');
else if (family === 'pull_request_review_comment' || family === 'issue_comment' || family === 'commit_comment') unique = [comment?.id || 'comment', comment?.updated_at || comment?.created_at || ''].join(':');
else if (family === 'pull_request') unique = [pr?.id || pr?.number || 'pr', pr?.head?.sha || '', pr?.updated_at || ''].join(':');
else if (family === 'issues') unique = [issue?.id || issue?.number || 'issue', issue?.updated_at || ''].join(':');
else if (family === 'check_run') unique = [checkRun?.id || 'check_run', checkRun?.completed_at || checkRun?.started_at || '', checkRun?.conclusion || checkRun?.status || ''].join(':');
else if (family === 'check_suite') unique = [checkSuite?.id || 'check_suite', checkSuite?.updated_at || '', checkSuite?.conclusion || checkSuite?.status || ''].join(':');
else if (family === 'release') unique = [release?.id || 'release', release?.updated_at || release?.published_at || ''].join(':');
else if (family === 'deployment_status') unique = String(deploymentStatus?.id || [deploymentStatus?.deployment_url || 'deployment_status', deploymentStatus?.created_at || '', deploymentStatus?.state || ''].join(':'));
else if (family === 'deployment') unique = String(deployment?.id || [deployment?.sha || '', deployment?.created_at || ''].join(':'));
else if (family === 'repository_vulnerability_alert') unique = [alert?.id || alert?.number || 'alert', alert?.updated_at || alert?.dismissed_at || ''].join(':');
else if (family === 'security_advisory') unique = [advisory?.ghsa_id || advisory?.id || 'advisory', advisory?.updated_at || advisory?.published_at || ''].join(':');
else if (family === 'push') unique = String(p.after || p.head_commit?.id || 'push');
else if (family === 'status') unique = [p.sha || 'sha', p.context || 'context', p.state || 'state', p.updated_at || p.created_at || ''].join(':');
else unique = [repo.id || repo.name || 'repository', repo.updated_at || '', action].join(':');
const fullName = repo.full_name || ['NTLx', repo.name || 'unknown'].join('/');
const entityNumber = pr?.number || issue?.number || '';
const inputRef = pr?.html_url || issue?.html_url || comment?.html_url || checkRun?.details_url || checkRun?.html_url || release?.html_url || repo.html_url || advisory?.html_url || alert?.html_url || '';
const title = pr?.title || issue?.title || checkRun?.name || checkSuite?.id || release?.name || release?.tag_name || advisory?.summary || alert?.dependency?.package?.name || family;
const occurredAt = review?.submitted_at || comment?.updated_at || comment?.created_at || pr?.updated_at || issue?.updated_at || checkRun?.completed_at || checkRun?.started_at || checkSuite?.updated_at || release?.published_at || release?.updated_at || deploymentStatus?.created_at || deployment?.created_at || advisory?.updated_at || alert?.updated_at || p.head_commit?.timestamp || p.updated_at || p.created_at || $now.toISO();
const workId = ['github', fullName, family, unique, action].join(':');
const summary = [family, action, 'on', fullName, entityNumber ? '#' + entityNumber : '', '-', String(title || '').replace(/\s+/g,' ').slice(0,300)].filter(Boolean).join(' ');
return { json: {
  work_id: workId, worker: 'hourly', kind, priority, source_event_id: workId, correlation_id: workId,
  project: 'github:' + fullName, input_ref: inputRef, summary, not_before: $now.toISO(), deadline: '',
  event_id: workId, event_occurred_at: occurredAt, event_source: 'n8n:github', event_category: 'github.' + family,
  event_title: summary, event_description: summary, event_status: 'scheduled', event_url: inputRef,
  event_metadata_object: JSON.stringify({ family, action, repository: fullName, entity_number: entityNumber, sender, conclusion, unique_key: unique, head_sha: pr?.head?.sha || checkRun?.head_sha || checkSuite?.head_sha || p.after || p.sha || '', ref: p.ref || deployment?.ref || '', context: p.context || '' }),
  should_enqueue: shouldEnqueue, family, action, repository: fullName, entity_number: entityNumber, sender, conclusion
} };

